import React, { useMemo, useState } from "react"
import { navigate } from "gatsby"

export interface RiverBand {
  key: string // series:<id> 或 tag:<名>
  label: string // 展示名：系列 title 或 tag 名
  kind: "series" | "tag"
  href: string // 点击跳转：系列带 → /series/<id>/，tag 带 → /tags/<slug>/
}

export interface RiverData {
  years: number[]
  bands: RiverBand[]
  counts: number[][] // counts[bandIdx][yearIdx]
}

interface TopicRiverProps {
  river: RiverData
}

const WIDTH = 960
const HEIGHT = 320
const PAD_Y = 16

interface Pt {
  x: number
  y: number
}

// Catmull-Rom → 三次贝塞尔，把折线点列转成平滑路径
function smoothPath(points: Pt[]): string {
  if (points.length < 2) return ""
  let d = `M${points[0].x.toFixed(1)},${points[0].y.toFixed(1)}`
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[Math.max(0, i - 1)]
    const p1 = points[i]
    const p2 = points[i + 1]
    const p3 = points[Math.min(points.length - 1, i + 2)]
    const c1x = p1.x + (p2.x - p0.x) / 6
    const c1y = p1.y + (p2.y - p0.y) / 6
    const c2x = p2.x - (p3.x - p1.x) / 6
    const c2y = p2.y - (p3.y - p1.y) / 6
    d += ` C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(
      1
    )} ${p2.x.toFixed(1)},${p2.y.toFixed(1)}`
  }
  return d
}

interface Stream {
  band: RiverBand
  total: number
  d: string
  // 颜色槽位按堆叠位置分配（自下而上 1..12），保证视觉上相邻的层
  // 恰好是色板上校验过色差的相邻槽位
  colorSlot: number
  // 各年份篇数，供 hover tip 显示「X 年 · N 篇」
  yearCounts: number[]
}

// ThemeRiver 布局：每列对称堆叠（中线为轴），最大列撑满可用高度。
// 堆叠顺序 inside-out：总量最大的层居中，其余交替向上下两侧堆，
// 大层轮廓稳定，小层在边缘不被挤压纠缠
function buildStreams(river: RiverData): Stream[] {
  const { years, bands, counts } = river
  const n = years.length
  const valueAt = (ti: number, yi: number): number => counts[ti]?.[yi] ?? 0
  const bandTotals = bands.map((_, ti) =>
    years.reduce((s, _y, yi) => s + valueAt(ti, yi), 0)
  )

  const byTotal = bands
    .map((_, ti) => ti)
    .sort((a, b) => bandTotals[b] - bandTotals[a])
  const above: number[] = []
  const below: number[] = []
  byTotal.slice(1).forEach((ti, i) => (i % 2 === 0 ? above : below).push(ti))
  // 自下而上的绘制顺序：below 反序 → 最大层 → above
  const stackOrder = [...below.slice().reverse(), byTotal[0], ...above]

  const colTotals = years.map((_, yi) =>
    bands.reduce((s, _t, ti) => s + valueAt(ti, yi), 0)
  )
  const maxTotal = Math.max(1, ...colTotals)
  const usable = HEIGHT - PAD_Y * 2
  const xAt = (yi: number): number => (yi / Math.max(1, n - 1)) * WIDTH
  const yScale = usable / maxTotal

  const acc = colTotals.map((t) => -t / 2)
  return stackOrder.map((ti, pos) => {
    const top: Pt[] = []
    const bottom: Pt[] = []
    for (let yi = 0; yi < n; yi++) {
      const v = valueAt(ti, yi)
      const base = acc[yi]
      bottom.push({ x: xAt(yi), y: HEIGHT / 2 + base * yScale })
      top.push({ x: xAt(yi), y: HEIGHT / 2 + (base + v) * yScale })
      acc[yi] = base + v
    }
    const d =
      smoothPath(top) +
      smoothPath([...bottom].reverse()).replace(/^M/, "L") +
      " Z"
    return {
      band: bands[ti],
      total: bandTotals[ti],
      d,
      colorSlot: (pos % 12) + 1,
      yearCounts: years.map((_, yi) => valueAt(ti, yi)),
    }
  })
}

function TopicRiver({ river }: TopicRiverProps): React.ReactElement | null {
  const [hovered, setHovered] = useState<string | null>(null)
  // 跟随鼠标的 tip 位置与所指年份（x 坐标 → 年份下标）
  const [tip, setTip] = useState<{ x: number; y: number; yearIdx: number } | null>(null)
  const streams = useMemo(() => buildStreams(river), [river])

  if (river.years.length < 2 || river.bands.length === 0) return null

  const firstYear = river.years[0]
  const lastYear = river.years[river.years.length - 1]
  const midYear = river.years[Math.floor((river.years.length - 1) / 2)]
  // 图例按篇数排名展示（读者关心头部主题），色点仍指向各自槽位色
  const legend = [...streams].sort((a, b) => b.total - a.total)
  const hoveredStream = streams.find((s) => s.band.key === hovered) ?? null

  const handleMove = (e: React.MouseEvent<SVGSVGElement>): void => {
    const rect = e.currentTarget.getBoundingClientRect()
    const x = e.clientX - rect.left
    const n = river.years.length
    const yearIdx = Math.min(
      n - 1,
      Math.max(0, Math.round((x / rect.width) * (n - 1)))
    )
    // 水平方向收进 tip 半宽，避免在河流两端被裁掉
    setTip({
      x: Math.min(Math.max(x, 76), rect.width - 76),
      y: e.clientY - rect.top,
      yearIdx,
    })
  }

  return (
    <div className="relative">
      <svg
        viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
        className="block w-full"
        role="img"
        aria-label={`主题河流：${firstYear} 到 ${lastYear} 年各系列与主题的文章数量变化`}
        onMouseMove={handleMove}
        onMouseLeave={() => setTip(null)}
      >
        {streams.map((s) => (
          <path
            key={s.band.key}
            d={s.d}
            fill={`var(--river-${s.colorSlot})`}
            // 2px 缝隙把堆叠的层彼此切开：亮色下透出所在表面底色（--river-gap），
            // 暗色下为微亮发丝缝，避免深色表面上出现黑色轮廓线
            stroke="var(--river-gap)"
            strokeWidth={2}
            strokeLinejoin="round"
            opacity={hovered === null || hovered === s.band.key ? 0.9 : 0.2}
            className="cursor-pointer transition-opacity duration-200"
            onMouseEnter={() => setHovered(s.band.key)}
            onMouseLeave={() => setHovered(null)}
            onClick={() => navigate(s.band.href)}
          />
        ))}
      </svg>

      {/* hover tip：跟随鼠标，反色胶囊，显示标签与所指年份的篇数 */}
      {hoveredStream && tip && (
        <div
          className="pointer-events-none absolute z-10 flex items-center gap-1.5 whitespace-nowrap rounded-full px-2.5 py-1 text-xs shadow-lg tabular-nums"
          style={{
            left: tip.x,
            top: tip.y,
            transform: "translate(-50%, calc(-100% - 10px))",
            background: "var(--text-primary)",
            color: "var(--bg-primary)",
          }}
        >
          <span
            className="inline-block h-2 w-2 rounded-full"
            style={{ background: `var(--river-${hoveredStream.colorSlot})` }}
          />
          <span className="font-medium">{hoveredStream.band.label}</span>
          <span className="opacity-50">·</span>
          {river.years[tip.yearIdx]} 年 · {hoveredStream.yearCounts[tip.yearIdx]} 篇
        </div>
      )}

      {/* 年份轴：首 / 中 / 末三刻度 */}
      <div className="mt-1 flex justify-between text-[10px] text-foreground-subtle tabular-nums">
        <span>{firstYear}</span>
        <span>{midYear}</span>
        <span>{lastYear}</span>
      </div>

      {/* 图例：按篇数排名，可点，hover 与河流联动 */}
      <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1">
        {legend.map((s) => (
          <button
            key={s.band.key}
            type="button"
            className="flex items-center gap-1 text-xs text-foreground-muted hover:text-foreground transition-colors"
            onMouseEnter={() => setHovered(s.band.key)}
            onMouseLeave={() => setHovered(null)}
            onClick={() => navigate(s.band.href)}
          >
            <span
              className="inline-block h-2 w-2 rounded-full"
              style={{ background: `var(--river-${s.colorSlot})` }}
            />
            {s.band.label}
            <span className="text-[10px] text-foreground-subtle tabular-nums">
              {s.total}
            </span>
          </button>
        ))}
      </div>
    </div>
  )
}

export default TopicRiver
